SELECT ?groupName (AVG(?value) AS ?agg) WHERE {
  ?airport a <http://www.semanticweb.org/ontologies/airport_ontology#Airport> .
  ?airport <http://www.semanticweb.org/ontologies/airport_ontology#locatedInCountry> ?groupNode .
  ?groupNode <http://www.semanticweb.org/ontologies/airport_ontology#countryName> ?groupName .
  ?airport <http://www.semanticweb.org/ontologies/airport_ontology#elevationFt> ?value .
} GROUP BY ?groupName ORDER BY DESC(?agg)

SELECT ?deptName (AVG(?cnt) AS ?agg) WHERE {
  SELECT ?person ?dept ?deptName (COUNT(?obj) AS ?cnt) WHERE {
    ?person <http://www.lehigh.edu/~zhp2/2004/0401/univ-bench.owl#worksFor> ?dept .
    ?dept <http://www.lehigh.edu/~zhp2/2004/0401/univ-bench.owl#name> ?deptName .
    ?person <http://www.lehigh.edu/~zhp2/2004/0401/univ-bench.owl#teacherOf> ?obj .
  } GROUP BY ?person ?dept ?deptName
} GROUP BY ?deptName ORDER BY DESC(?agg)

SELECT ?deptName (AVG(?cnt) AS ?agg) WHERE {
  SELECT ?person ?dept ?deptName (COUNT(?obj) AS ?cnt) WHERE {
    ?person <http://www.lehigh.edu/~zhp2/2004/0401/univ-bench.owl#worksFor> ?dept .
    ?dept <http://www.lehigh.edu/~zhp2/2004/0401/univ-bench.owl#name> ?deptName .
    ?person <http://www.lehigh.edu/~zhp2/2004/0401/univ-bench.owl#teacherOf> ?obj .
  } GROUP BY ?person ?dept ?deptName
} GROUP BY ?deptName ORDER BY DESC(?agg)
